import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"x.com 投稿用下書き — 日本語 thread (polyglot voice)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v0.5/x-thread-ja.md","filePath":"announcements/v0.5/x-thread-ja.md"}'),i={name:"announcements/v0.5/x-thread-ja.md"};function l(n,a,s,c,p,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="x-com-投稿用下書き-—-日本語-thread-polyglot-voice" tabindex="-1">x.com 投稿用下書き — 日本語 thread (polyglot voice) <a class="header-anchor" href="#x-com-投稿用下書き-—-日本語-thread-polyglot-voice" aria-label="Permalink to &quot;x.com 投稿用下書き — 日本語 thread (polyglot voice)&quot;">​</a></h1><blockquote><p>投稿先 ... <a href="https://x.com/cardene777" target="_blank" rel="noreferrer">@cardene777</a> Voice ... 本人名義 / 個人 dev 視点 / 「作ったよ」 maker トーン 動画 ... <code>assets/kiwa-promo-ja.mp4</code> (7.1MB / 80s) を 1 ツイート目に添付 想定 ... 1 ツイート 140 字以内 全 8 ツイート、 番号 [1/8] 付き</p></blockquote><hr><h2 id="_1-8-動画添付" tabindex="-1">[1/8] (動画添付) <a class="header-anchor" href="#_1-8-動画添付" aria-label="Permalink to &quot;[1/8] (動画添付)&quot;">​</a></h2><p>「test stack が runner ごとに散らばってる」 を 1 spec で解決する polyglot test toolchain 「kiwa」 を v0.5 まで仕上げました。</p><p>contract / API / component / e2e / a11y / visual を 1 つの spec から並列生成、 release で Coverage + Mutation 両 gate を物理 enforce。</p><p>80s 動画 ↓</p><p><a href="https://github.com/cardene777/kiwa" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa</a></p><p>#OSS #testing</p><hr><h2 id="_2-8" tabindex="-1">[2/8] <a class="header-anchor" href="#_2-8" aria-label="Permalink to &quot;[2/8]&quot;">​</a></h2><p>何が嬉しいか ... Foundry / Hardhat / Vitest / Playwright / msw / axe-core / pixelmatch / pytest を <strong>1 つの Layer 1 spec から自動生成</strong>、 runner ごとに同じ観点を書き直す必要がなくなります。</p><p>「stack 横断の単一ソース」 が手に入る感覚です。</p><hr><h2 id="_3-8" tabindex="-1">[3/8] <a class="header-anchor" href="#_3-8" aria-label="Permalink to &quot;[3/8]&quot;">​</a></h2><p>対応 layer は 6 surface ...</p><ol><li>Contract (Foundry / Hardhat)</li><li>API integration (msw / supertest)</li><li>Component (8 framework adapter)</li><li>E2E (Playwright + anvil + viem)</li><li>A11y / Visual (axe-core / pixelmatch)</li><li>Data / CLI / Observability (queue / shell IO / flaky 検出)</li></ol><p>dApp / smart contract は対応分野の 1 つです。</p><hr><h2 id="_4-8" tabindex="-1">[4/8] <a class="header-anchor" href="#_4-8" aria-label="Permalink to &quot;[4/8]&quot;">​</a></h2><p>言語横断対応 (polyglot)</p><ul><li><strong>TypeScript</strong> ... 11 npm package</li><li><strong>Python</strong> ... 1 PyPI package (kiwa-test-py)</li><li><strong>Solidity</strong> ... Foundry / Hardhat 連携</li></ul><p>Rust / Go は構想中。 「default は TS だけど Python の service と Solidity の contract も同じ spec で test できる」 のが kiwa の独自性です。</p><hr><h2 id="_5-8" tabindex="-1">[5/8] <a class="header-anchor" href="#_5-8" aria-label="Permalink to &quot;[5/8]&quot;">​</a></h2><p>v0.5 の目玉 ... 全 11 npm package で MSI ≥ 80 を release workflow で物理 enforce しました。</p><ul><li>@kiwa-lab/api ... 96.06 %</li><li>@kiwa-lab/a11y ... 93.62 %</li><li>@kiwa-lab/ui ... 91.76 %</li><li>全 package ≥ 80 通過</li></ul><p>Coverage gate (Lines 90+ / Branches 80+) も維持。</p><hr><h2 id="_6-8" tabindex="-1">[6/8] <a class="header-anchor" href="#_6-8" aria-label="Permalink to &quot;[6/8]&quot;">​</a></h2><p>Component test (<code>@kiwa-lab/ui</code>) は 1 package で 8 surface 対応 ...</p><p>React / Vue 3 / Svelte / SolidJS / Lit / Qwik / Angular + 実 Chromium</p><p>全 adapter が <code>mode + stop()</code> 契約共有。 thin wrapper なので新 framework 追加も 1 PR 100 行レベルです。</p><hr><h2 id="_7-8" tabindex="-1">[7/8] <a class="header-anchor" href="#_7-8" aria-label="Permalink to &quot;[7/8]&quot;">​</a></h2><p>設計判断のキモ ... mutation gate を <strong>package 別 threshold</strong> にしたこと。 pure-logic 系 (api / a11y / ui setup-component-env+lit) は 90 % 強制、 thin wrapper 系 (vue / solid / svelte / qwik / angular / e2e / cli / observability / visual / spec / core) は 80 % 固定。</p><p>equivalent mutant の壁を現実的に超えました。</p><hr><h2 id="_8-8" tabindex="-1">[8/8] <a class="header-anchor" href="#_8-8" aria-label="Permalink to &quot;[8/8]&quot;">​</a></h2><p>stack に test 散乱を感じる方、 ぜひ触ってみてください。</p><p>📖 README <a href="https://github.com/cardene777/kiwa" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa</a> 💬 Discussions <a href="https://github.com/cardene777/kiwa/discussions/451" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/discussions/451</a> 📦 <code>npm install @kiwa-lab/core</code> 🐍 <code>pip install kiwa-test-py</code></p><p>質問・要望は Issue / Discussion / リプライ歓迎です 🌱</p>',42)])])}const m=e(i,[["render",l]]);export{u as __pageData,m as default};
